  "settings.modelProvider.fieldHelp": "À propos de {field}",
  "settings.modelProvider.help.contextWindow": "Capacité de contexte que le modèle peut traiter en une fois, en tokens. ZAICODE l'utilise pour gérer le contexte.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.maxOutputTokens": "Nombre maximal de tokens qu'une seule requête au modèle peut générer.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.inputModalities": "Définir les types de contenu que le modèle peut recevoir :\n\n- **Texte** : reçoit du contenu texte. Obligatoire.\n- **Images** : reçoit du contenu image.\n- **Vidéo** : reçoit du contenu vidéo.\n- **PDF** : reçoit directement des documents PDF.",
  "settings.modelProvider.help.outputModalities": "Type de contenu des réponses du modèle. Seul le texte est actuellement pris en charge.",
  "settings.modelProvider.help.capabilities": "- **Sortie structurée** : prend en charge les contraintes JSON Schema sur les champs, types et structure de sortie.\n- **Recherche web native** : prend en charge la recherche web intégrée à l'API du modèle.\n- **Messages système en cours de conversation** : permet d'insérer des instructions système pendant une conversation.\n\nN'activez pas des capacités que le modèle ne prend pas en charge.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Définir les niveaux de raisonnement disponibles dans le chat. **Ils doivent être ordonnés du raisonnement le plus faible au plus élevé**.\nNe configurez pas de niveaux de raisonnement non pris en charge par le modèle.",
  "settings.modelProvider.help.reasoningLevelMapping": "Utilisez une expression CEL pour mapper le niveau de raisonnement actuel, `reasoningLevel`, vers les champs de requête de l'API du modèle. L'objet JSON renvoyé par l'expression est fusionné dans le corps de la requête envoyée.",
  "settings.modelProvider.help.advanced": "**Schéma d'outil MFJS** : active la compatibilité Moonshot Flavored JSON Schema, couramment utilisée par l'API du modèle Kimi de Moonshot. À n'activer que si l'API du modèle exige ce format.",
  "settings.modelProvider.help.followRecommendedConfig": "Correspond à la configuration recommandée selon l'ID du modèle, l'URL de base et le format d'API. ZAICODE met à jour en continu les recommandations et vous les synchronise automatiquement.\nLorsque vous modifiez un paramètre manuellement, celui-ci devient géré manuellement et cesse de suivre les mises à jour des recommandations ; les autres paramètres restent gérés par la configuration intelligente.",
